nt) {\r\n            text = texts.selectedItemCount.replace('#', selectedItemCount);\r\n        } else {\r\n            if (selectedItemCount >= 1) {\r\n                text = selected.map(item => item.text).join(', ');\r\n            }\r\n        }\r\n\r\n        return text;\r\n    };\r\n\r\n    getSelectedItems = items => items.filter(item => item.checked);\r\n\r\n    onToggle = () => {\r\n        this.setState(prevState => {\r\n            return { opened: !prevState.opened };\r\n        });\r\n    };\r\n\r\n    onSelectAll = event => {\r\n        const items = [...this.state.items];\r\n        const totalItems = items.length;\r\n        for (let i = 0; i < totalItems; i++) {\r\n            if (items[i].visible === undefined || items[i].visible) {\r\n                items[i] = { ...items[i], checked: event.target.checked };\r\n            }\r\n        }\r\n\r\n        this.props.onChange && this.props.onChange(this.getSelectedItems(items));\r\n        this.setState({ items });\r\n    };\r\n\r\n    onSelect = (item, event) => {\r\n        const items = [...this.state.items];\r\n        const index = items.findIndex(x => x.id === item.id);\r\n        items[index] = { ...items[index], checked: event.target.checked };\r\n\r\n        this.props.onChange && this.props.onChange(this.getSelectedItems(items));\r\n        this.setState({ items });\r\n    };\r\n\r\n    onSearch = value => {\r\n        const items = [...this.state.items],\r\n            totalItems = items.length;\r\n        for (let i = 0; i < totalItems; i++) {\r\n            items[i] = { ...items[i], visible: items[i].text.toLowerCase().indexOf(value.toLowerCase()) !== -1 };\r\n        }\r\n\r\n        this.setState({ searchTerm: value, items });\r\n    };\r\n\r\n    renderSearchBox = () => {\r\n        if (!this.props.hasSearchBox || this.state.items.length === 0) {\r\n            return null;\r\n        }\r\n\r\n        return (\r\n            <div className=\"react-multiselect-search-box\">\r\n                <input autoFocus onChange={event => this.onSearch(event.target.value)}\r\n                    ref={element => this.searchInputBox = element}\r\n                    value={this.state.searchTerm} type=\"text\" placeholder=\"Search data\" />\r\n                <span className=\"clear-indicator\" onClick={() => this.onSearch('')}>\r\n                    <svg height=\"20\" width=\"20\" viewBox=\"0 0 20 20\" focusable=\"false\">\r\n                        <path d=\"M14.348 14.849c-0.469 0.469-1.229 0.469-1.697 0l-2.651-3.030-2.651 3.029c-0.469 0.469-1.229 0.469-1.697 0-0.469-0.469-0.469-1.229\r\n                            0-1.697l2.758-3.15-2.759-3.152c-0.469-0.469-0.469-1.228 0-1.697s1.228-0.469 1.697 0l2.652 3.031\r\n                            2.651-3.031c0.469-0.469 1.228-0.469 1.697 0s0.469 1.229 0 1.697l-2.758 3.152 2.758 3.15c0.469 0.469 0.469 1.229 0 1.698z\"\r\n                        />\r\n                    </svg>\r\n                </span>\r\n            </div>\r\n        );\r\n    };\r\n\r\n    render() {\r\n        const { items, opened } = this.state;\r\n        const selected = items.filter(item => item.checked);\r\n        const selectedText = this.getSelectedText(this.props, items);\r\n\r\n        return (\r\n            <div id={this.id} className=\"react-multiselect\" ref={element => this.wrapper = element}\r\n                style={{ width: this.props.width ? this.props.width : '100%' }}>\r\n                <div className=\"react-multiselect-dropdown-button\" onClick={this.onToggle}>\r\n                    <span className=\"selected-text\">{selectedText}</span>\r\n                    <span className=\"dropdown-indicator\">\r\n                        <svg height=\"20\" width=\"20\" viewBox=\"0 0 20 20\" focusable=\"false\">\r\n                            <path d=\"M4.516 7.548c0.436-0.446 1.043-0.481 1.576 0l3.908 3.747 3.908-3.747c0.533-0.481 1.141-0.446 1.574 0\r\n                                0.436 0.445 0.408 1.197 0 1.615-0.406 0.418-4.695 4.502-4.695 4.502-0.217 0.223-0.502 0.335-0.787\r\n                                0.335s-0.57-0.112-0.789-0.335c0 0-4.287-4.084-4.695-4.502s-0.436-1.17 0-1.615z\"\r\n                            />\r\n                        </svg>\r\n                    </span>\r\n                </div>\r\n                <div className={`react-multiselect-dropdown-list ${opened ? '' : 'hidden'}`}>\r\n                    {this.renderSearchBox()}\r\n                    {\r\n                        items.filter(item => item.visible === undefined || item.visible).length > 0 &&\r\n                        <div className=\"react-multiselect-select-all\">\r\n                            <div className=\"checkbox-wrapper\">\r\n                                <div>\r\n                                    <input type=\"checkbox\" id={`${this.id}-selectAll`}\r\n                                        checked={items.length === selected.length}\r\n                                        onChange={this.onSelectAll}\r\n                                    />\r\n                                    <label htmlFor={`${this.id}-selectAll`}> Sellect all</label>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    }\r\n                    {\r\n                        items.length > 0 &&\r\n                        <div className=\"react-multiselect-items\">\r\n                            {\r\n                                items.map(item => {\r\n                                    return item.visible === undefined || item.visible ?\r\n                                        <ul key={item.id}>\r\n                                            <li className=\"react-multiselect-item\">\r\n                                                <div className=\"checkbox-wrapper\">\r\n                                                    <div>\r\n                                                        <input type=\"checkbox\" id={`${this.id}-${item.id}`}\r\n                                                            checked={item.checked}\r\n                                                            onChange={event => this.onSelect(item, event)}\r\n                                                        />\r\n                                                        <label htmlFor={`${this.id}-${item.id}`}> {item.text}</label>\r\n                                                    </div>\r\n                                                </div>\r\n                                            </li>\r\n                                        </ul> : null;\r\n                                })\r\n                            }\r\n                        </div>\r\n                    }\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { PureComponent } from 'react';\r\n\r\nexport default class StickyBlock extends PureComponent {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            showStickyHeader: false\r\n        };\r\n    }\r\n\r\n    componentDidMount() {\r\n        window.addEventListener('scroll', this.handleToggleSticky);\r\n    }\r\n\r\n    componentWillUnmount() {\r\n        window.removeEventListener('scroll', this.handleToggleSticky);\r\n    }\r\n\r\n    handleToggleSticky = () => {\r\n        if (window.scrollY > this.props.threshold) {\r\n            if (!this.state.showStickyHeader) {\r\n                this.setState({ showStickyHeader: true });\r\n            }\r\n        } else {\r\n            if (this.state.showStickyHeader) {\r\n                this.setState({ showStickyHeader: false });\r\n            }\r\n        }\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <div className={`sticky-block ${this.state.showStickyHeader ? '' : 'hidden'}`}>\r\n                {this.props.children}\r\n            </div>\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport ReactDOM from 'react-dom';\r\nimport axios from 'axios';\r\n\r\nimport { axiosError, resolveClientUrl } from '../../../common-functions';\r\nimport getResource from '../../../resourceHelper';\r\nimport Breadcrumb from '../../../shared/components/Breadcrumb';\r\nimport SearchForm from './SearchForm';\r\nimport Table from './Table';\r\nimport { PerformanceProcess } from '../../../constants';\r\n\r\nexport default class PRTracking extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            filter: {\r\n                groups: [],\r\n                employees: [],\r\n                noPR: false\r\n            },\r\n            groupOptions: [],\r\n            employeeOptions: [],\r\n            tableData: null,\r\n            period: null\r\n        };\r\n\r\n        this.employees = [];\r\n    }\r\n\r\n    componentDidMount() {\r\n        const promises = [\r\n            axios(resolveClientUrl('PRTracking/GetGroupsAndMembers'))\r\n        ];\r\n\r\n        Promise.all(promises)\r\n            .then(([response]) => {\r\n                const groupOptions = response.data.groups.map(group => {\r\n                    return {\r\n                        id: group.groupId,\r\n                        text: group.name,\r\n                        checked: true\r\n                    };\r\n                });\r\n\r\n                this.employees = response.data.employees;\r\n\r\n                const employeeOptions = response.data.employees.map(item => {\r\n                    return {\r\n                        id: item.employeeId,\r\n                        text: `${item.nickName} (${item.fullName})`,\r\n                        checked: true\r\n                    };\r\n                });\r\n\r\n                const filter = {\r\n                    ... this.state.filter,\r\n                    groups: groupOptions,\r\n                    employees: employeeOptions\r\n                };\r\n\r\n                this.setState({ filter, employeeOptions, groupOptions }, this.getPRTracking);\r\n            }).catch(axiosError);\r\n    }\r\n\r\n    handleFilterChange = (name, value) => {\r\n        if (name === 'groups') {\r\n            const employeeChoosens = this.employees.filter(e => value.some(v => v.id === e.groupId))\r\n                .map(e => ({\r\n                    id: e.employeeId,\r\n                    text: `${e.nickName} (${e.fullName})`,\r\n                    checked: true\r\n                }));\r\n\r\n            this.setState({\r\n                employeeOptions: employeeChoosens,\r\n                filter: {\r\n                    ...this.state.filter,\r\n                    [name]: value,\r\n                    employees: employeeChoosens\r\n                }\r\n            });\r\n        } else {\r\n            this.setState({\r\n                filter: {\r\n                    ...this.state.filter,\r\n                    [name]: value\r\n                }\r\n            });\r\n        }\r\n    };\r\n\r\n    getPRTracking = () => {\r\n        const filter = this.state.filter;\r\n\r\n        axios.get(resolveClientUrl('PRTracking/Get'), {\r\n            params: {\r\n                noPR: filter.noPR,\r\n                employeeIds: filter.employees.map(x => x.id).toString()\r\n            }\r\n        }).then(response => {\r\n            this.setState({\r\n                tableData: response.data.employees.reduce(function (groups, item) {\r\n                    item.selfPRQuantity = item.details.filter(d => d.roleId === PerformanceProcess.Self).reduce((current, i) => current + i.quantity, 0);\r\n                    item.pmPRQuantity = item.details.filter(d => d.roleId === PerformanceProcess.ProjectManager).reduce((current, i) => current + i.quantity, 0);\r\n                    item.evaluatorPRQuantity = item.details.filter(d => d.roleId === PerformanceProcess.Evaluator).reduce((current, i) => current + i.quantity, 0);\r\n                    item.reviewerPRQuantity = item.details.filter(d => d.roleId === PerformanceProcess.Reviewer).reduce((current, i) => current + i.quantity, 0);\r\n\r\n                    let group = groups.find(e => e.groupId === item.groupId);\r\n\r\n                    if (!group) {\r\n                        group = {\r\n                            groupId: item.groupId,\r\n                            groupName: item.groupName,\r\n                            employees: [item]\r\n                        };\r\n\r\n                        groups.push(group);\r\n                    } else {\r\n                        group.employees.push(item);\r\n                    }\r\n\r\n                    return groups;\r\n                }, []),\r\n                period: response.data.period\r\n            });\r\n        }).catch(axiosError);\r\n    };\r\n    render() {\r\n        const { filter, period, groupOptions, employeeOptions, tableData } = this.state;\r\n\r\n        return (\r\n            <div className=\"row\">\r\n                <Breadcrumb>\r\n                    <li className=\"current\">{getResource('PRReport')}</li>\r\n                </Breadcrumb>\r\n                <div className=\"col-sm-12\">\r\n                    {\r\n                        this.employees.length > 1 && groupOptions.length > 0 &&\r\n                        <SearchForm filter={filter}\r\n                            groupOptions={groupOptions}\r\n                            employeeOptions={employeeOptions}\r\n                            onFilterChange={this.handleFilterChange}\r\n                            onSubmit={this.getPRTracking}\r\n                        />\r\n                    }\r\n\r\n                    <Table tableData={tableData}\r\n                        period={period}\r\n                    />\r\n                </div>\r\n            </div>\r\n        );\r\n    }\r\n}\r\n\r\nReactDOM.render(<PRTracking />, document.getElementById('pr-tracking-wrapper'));","import React, { Component } from 'react';\r\nimport { Form, FormGroup, ControlLabel, Button } from 'react-bootstrap';\r\n\r\nimport getResource from '../../../resourceHelper';\r\nimport Multiselect from '../../../shared/components/react-multiselect/index';\r\n\r\nexport default class SearchForm extends Component {\r\n    handleGroupChange = selectedOption => {\r\n        this.props.onFilterChange('groups', selectedOption);\r\n    };\r\n\r\n    handleEmployeeChange = selectedOption => {\r\n        this.props.onFilterChange('employees', selectedOption);\r\n    };\r\n\r\n    handleNoPRChange = event => {\r\n        this.props.onFilterChange('noPR', event.target.checked);\r\n    };\r\n\r\n    handleSubmit = event => {\r\n        event.preventDefault();\r\n        this.props.onSubmit();\r\n    };\r\n\r\n    render() {\r\n        const { filter, groupOptions, employeeOptions } = this.props;\r\n\r\n        return (\r\n            <Form inline className=\"form-filter\" onSubmit={this.handleSubmit}>\r\n                {\r\n                    groupOptions.length > 1 &&\r\n                    <FormGroup>\r\n                        <ControlLabel>{getResource('Team')}</ControlLabel>\r\n                        <div className=\"control-content team-width pr-tracking-search-form\">\r\n                            <Multiselect hasSearchBox\r\n                                items={groupOptions}\r\n                                onChange={this.handleGroupChange}\r\n                            />\r\n                        </div>\r\n                    </FormGroup>\r\n                }\r\n\r\n                <FormGroup>\r\n                    <ControlLabel>{getResource('Employee')}</ControlLabel>\r\n                    <div className=\"control-content employee-width pr-tracking-search-form\">\r\n                        <Multiselect hasSearchBox\r\n                            items={employeeOptions}\r\n                            onChange={this.handleEmployeeChange}\r\n                        />\r\n                    </div>\r\n                </FormGroup>\r\n                <FormGroup>\r\n                    <div className=\"checkbox\">\r\n                        <input type=\"checkbox\" name=\"noPR\"\r\n                            checked={filter.noPR}\r\n                            onChange={this.handleNoPRChange} id=\"noPR\" className=\"checkbox-custom\"\r\n                        />\r\n                        <label htmlFor=\"noPR\">No PR</label>\r\n                    </div>\r\n                </FormGroup>\r\n                <FormGroup>\r\n                    <Button type=\"submit\" bsStyle=\"primary\">{getResource('Search')}</Button>\r\n                </FormGroup>\r\n            </Form>\r\n        );\r\n    }\r\n}","import React, { Component, Fragment } from 'react';\r\nimport { Tooltip, OverlayTrigger } from 'react-bootstrap';\r\n\r\nimport getResource from '../../../resourceHelper';\r\nimport StickyBlock from '../../../shared/components/StickyBlock';\r\nimport { PerformanceProcess, EmptyPlaceHolder } from '../../../constants';\r\nimport { noDataIndication } from '../../../common-functions';\r\n\r\nexport default class Table extends Component {\r\n    getOverlay = details => {\r\n        if (details.length > 0) {\r\n            return (<Tooltip id=\"tooltip\">{details.map(d => <p className=\"creator-item\" key={d.creatorId}>{d.creatorNickname}: {d.quantity}</p>)}</Tooltip>);\r\n        }\r\n\r\n        return <Fragment />;\r\n    };\r\n\r\n    renderEmployee = (employee, index) => (\r\n        <tr key={employee.employeeId}>\r\n            <td className=\"text-center\">{index + 1}</td>\r\n            <td>{employee.nickName} ({employee.fullName})</td>\r\n            <td>{employee.jobTitle}</td>\r\n            <td className=\"text-center\">{employee.selfPRQuantity > 0 ? employee.selfPRQuantity : EmptyPlaceHolder}</td>\r\n            <td className=\"text-center\">\r\n                <OverlayTrigger placement=\"bottom\" overlay={this.getOverlay(employee.details.filter(d => d.roleId === PerformanceProcess.ProjectManager))}>\r\n                    <span className=\"pr-quantity\">{employee.pmPRQuantity > 0 ? employee.pmPRQuantity : EmptyPlaceHolder}</span>\r\n                </OverlayTrigger>\r\n            </td>\r\n\r\n            <td className=\"text-center\">\r\n                <OverlayTrigger placement=\"bottom\" overlay={this.getOverlay(employee.details.filter(d => d.roleId === PerformanceProcess.Evaluator))}>\r\n                    <span className=\"pr-quantity\">{employee.evaluatorPRQuantity > 0 ? employee.evaluatorPRQuantity : EmptyPlaceHolder}</span>\r\n                </OverlayTrigger>\r\n            </td>\r\n            <td className=\"text-center\">\r\n                <OverlayTrigger placement=\"bottom\" overlay={this.getOverlay(employee.details.filter(d => d.roleId === PerformanceProcess.Reviewer))}>\r\n                    <span className=\"pr-quantity\">{employee.reviewerPRQuantity > 0 ? employee.reviewerPRQuantity : EmptyPlaceHolder}</span>\r\n                </OverlayTrigger>\r\n            </td>\r\n\r\n        </tr>\r\n    );\r\n\r\n    renderData = data => {\r\n        return (\r\n            <Fragment key={data.groupId}>\r\n                <tr className=\"team-group-row\">\r\n                    <td colSpan={7}>{data.groupName}</td>\r\n                </tr>\r\n                {data.employees.map(this.renderEmployee)}\r\n            </Fragment >\r\n        );\r\n    };\r\n\r\n    renderPRTrackingTableContent = () => {\r\n        if (this.props.tableData) {\r\n            if (this.props.period) {\r\n                return (\r\n                    <Fragment>\r\n                        <tr className=\"group-row\">\r\n                            <td colSpan={7}>{this.props.period.name}</td>\r\n                        </tr>\r\n                        {this.props.tableData.length > 0 ? this.props.tableData.map(this.renderData) :\r\n                            <tr><td className=\"text-center\" colSpan={7}>{noDataIndication()}</td></tr>\r\n                        }\r\n                    </Fragment>);\r\n            } else {\r\n                return (<tr><td className=\"text-center\" colSpan={7}>{noDataIndication()}</td></tr>);\r\n            }\r\n        } else {\r\n            return <Fragment />;\r\n        }\r\n    };\r\n\r\n    renderPRTrackingStickyTable = () => {\r\n       return (\r\n            <table className=\"table table-bordered table-striped pr-tracking-table\" id=\"pr-tracking-sticky\">\r\n                <thead>\r\n                    <tr>\r\n                        <th rowSpan=\"2\" className=\"order\" >{getResource('SymbolCount')}</th>\r\n                        <th className=\"nick-name \" rowSpan=\"2\">{getResource('Employee')}</th>\r\n                        <th rowSpan=\"2\" className=\"job-title\">{getResource('JobTitle')}</th>\r\n                        <th colSpan=\"4\">Performance Record Quantity</th>\r\n                    </tr>\r\n                    <tr>\r\n                        <th className=\"stick-block self\">{getResource('Self')}</th>\r\n                        <th className=\"stick-block pm\">{getResource('ProjectManager')}</th>\r\n                        <th className=\"evaluator stick-block\">{getResource('Evaluator')}</th>\r\n                        <th className=\"reviewer stick-block\">{getResource('Reviewer')}</th>\r\n                    </tr>\r\n                </thead>\r\n            </table>\r\n\r\n        );\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <Fragment>\r\n                <StickyBlock threshold={236}>\r\n                {\r\n                        this.renderPRTrackingStickyTable()\r\n                }\r\n                </StickyBlock>\r\n                <table id=\"pr-tracking-table\" className=\"table table-bordered pr-tracking-table table-striped\">\r\n                    <thead>\r\n                        <tr>\r\n                            <th className=\"order\" rowSpan=\"2\">{getResource('SymbolCount')}</th>